/* English companion to the Chinese deck. Published aggregates are shared. */
globalThis.SLIDES = (() => {
  const {flow,math,mi,mn,mo,mt,sub}=V;
  const f=(s,l)=>math(s,l);
  const note=s=>`<div class="callout">${s}</div>`;
  const caution=s=>`<div class="callout caution">${s}</div>`;
  const two=(a,b,cls='')=>`<div class="two ${cls}"><div>${a}</div><div>${b}</div></div>`;
  const table=(heads,rows,caption='')=>`<div class="table-wrap"><table class="data-table">${caption?`<caption>${caption}</caption>`:''}<thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>i?`<td>${c}</td>`:`<th scope="row">${c}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const group=g=>`<span class="group group-${g.toLowerCase()}">${g}</span>`;
  const slides=[];
  function add(chapter,title,lead,body,notes,source,figure=''){slides.push({chapter,title,lead,body,notes,source,figure});}
  add('The research question','From simulated events to feature comparisons','33 slides on how the paper turns a choice of physical inputs into a statistical comparison.',
    two(`<div class="cover-equation">H → ZZ* → 2e2μ</div>${V.decay()}`,`<h3>How do different network inputs<br>change the final inference?</h3><p>Follow an event through the analysis, then read the results.</p><div class="insight"><b>19</b><span>inputs in four groups: A/B/C/D</span></div><div class="insight"><b>15 × 5</b><span>nonempty subsets × training seeds</span></div><div class="insight"><b>W₆₈</b><span>Width of a nominal 68% interval for μ.<br>A smaller value means a narrower interval.</span></div>`),
    `<p>This guide assumes basic calculus, vectors and probability, but no background in this project, machine learning or experimental particle physics. Slides 2–3 connect signal strength, intervals, widths and the reason for comparing widths. Slides 23–28 explain the comparison mathematics in detail.</p><p>Detailed explanations are open by default and can be collapsed. Use arrow keys or PageUp/PageDown to navigate; keys inside interactive controls retain their usual function. The contents menu and page number provide direct access. The language link keeps the current slide number.</p><p>This is an educational and technical study of controlled Monte Carlo (MC) simulations. It is not an ATLAS/CMS result, a Higgs discovery or a physics measurement. Conclusions apply to the specified analysis workflow.</p>`,'Abstract; § I Introduction');
  add('First steps: μ and intervals','μ scales the signal; an interval constrains μ','First ask how much signal is expected, then ask how tightly the data constrain that multiplier.',
    `${f(`${mi('λ')}${mo('=')}${mi('μ')}${mi('s')}${mo('+')}${mi('b')}`,'The total expected count lambda equals mu times reference signal s plus background b')}${two(`${table(['μ','Signal μs','Background b','Total μs+b'],[['0','0','2','2'],['1','3','2','5'],['2','6','2','8']],'Teaching counts: reference signal s=3, background b=2.')}<p class="small">μ=1 uses the reference signal; μ=2 doubles it.<br>These are means, not guaranteed observed counts.</p>`,`<h3>Why give a range?</h3><p>Counts fluctuate and templates have uncertainty, so data usually allow a range of μ values.</p><div class="result-line"><strong>For example: [0.3, 1.7]</strong><br>A range retained by a statistical rule.<br>0.3 is its lower endpoint; 1.7 is its upper endpoint.</div><p class="small">The interval is a range of μ, not a range of event counts or network scores.</p>`)}${note('Here μ is a dimensionless signal-strength parameter for the whole population. In 2e2μ, the same letter denotes a muon. A network scores individual events; it does not directly output signal strength.')}`,
    `<p>s is the reference signal expectation at μ=1, b is the background expectation, and λ is their total. Only the signal is multiplied by μ. Thus μ=0 retains background events, and μ=2 doubles the signal expectation rather than doubling the total count.</p><p>Several values of μ can produce the same observed count, with different likelihoods. A prescribed likelihood threshold retains a range of candidate values. Slides 19–21 explain Poisson counts, nuisance parameters and profile likelihood.</p><p>The target 68% coverage means that, under the specified model, approximately 68% of intervals constructed in repeated experiments should contain the fixed true μ. It does not mean that 68% of events fall inside the interval, or assign a posterior probability to μ in a particular observed interval. The paper uses an asymptotic threshold and therefore calls these intervals nominal; their actual coverage needs validation.</p><p>The count table and [0.3,1.7] are separate hand-written examples. That interval was not fitted from s=3, b=2 and is not a published subset result.</p>`,'§ IV B; eq:likelihood; eq:profile (teaching examples)');
  add('First steps: width and comparison','Width = upper endpoint − lower endpoint','Put two μ intervals on the same scale to understand the quantity the paper compares.',
    `${two(V.intervalBasics(),`<h3>Calculate W₆₈</h3>${f(`${sub('W',68)}${mo('=')}${sub('μ','up')}${mo('−')}${sub('μ','low')}`,'Interval width is the upper mu endpoint minus the lower endpoint')}<div class="insight"><b>1.4</b><span>Method I: 1.7 − 0.3</span></div><div class="insight"><b>1.8</b><span>Method II: 1.9 − 0.1</span></div><p>Method I leaves a smaller range of μ:<br><strong>a tighter nominal constraint.</strong></p>`)}${note('<strong>Why compare widths?</strong> Each subset constrains the same μ using the same confidence level and inference method. Sorting W₆₈ from small to large compares nominal precision.')}${caution('Both intervals are teaching examples. A narrower interval still needs coverage and independent validation to establish reliability.')}`,
    `<p>Both μ and W₆₈ are dimensionless. Width is the upper endpoint minus the lower endpoint, not the upper endpoint alone, a half-width, or the number 68%. The example widths are 1.4 and 1.8. Profile intervals can be asymmetric, so μ̂±W/2 is not a general representation.</p><p>The scientific objective is a constraint on signal strength. Each subset produces a separately trained network, category signal/background yields and template uncertainties, then an interval from the same inference procedure. Width supplies a common scale for the final output of that chain; raw variables with different units are not ranked against one another.</p><p>The paper uses each candidate's own nominal Asimov expectation at μ=1 as the no-fluctuation data vector and applies T1 inference. Each subset has five widths, and the main ranking sorts their median. A chance narrow interval in one random experiment is not the ranking criterion.</p><p>A smaller W₆₈ describes nominal precision under this model and rule. Underestimated uncertainty can also produce a narrow interval. MC fluctuations, coverage and independent validation are required to assess whether an apparent benefit is reliable. AUC measures event ordering and answers a different question.</p><details><summary>Check: what is the width of [0.4,1.6]? Does it establish reliability?</summary><p>The width is 1.2. Reliability also requires appropriate coverage and model validity.</p></details>`,'§ IV B; eq:width; § V A (teaching intervals)');
  add('The research question','Six steps form one evidence chain','The classifier is an intermediate step. The main comparison comes from statistical inference.',
    `${flow([['Simulated events','Existing signal/background ROOT samples'],['Reconstruct features','Four leptons → 19 inputs'],['Train networks','Train each subset separately']])}${flow([['Define categories','Scores → low/high counts'],['Build likelihood','Category yields → interval for μ'],['Compare and validate','Width, attribution and stability']],4)}${note('x describes an event; score is a network output; μ scales the expected signal; W₆₈ is the upper minus lower endpoint of the μ interval.')}`,
    `<p>Keep event-level and population-level quantities distinct. One MC record describes a simulated collision. The classifier reads its kinematic features and produces a score. Scores partition many weighted events into categories; sums of weights estimate each category's signal and background expectations. A count likelihood then constrains the population parameter μ.</p><p>μ=1 uses the configured signal prediction, μ=0 removes that signal component, and μ=2 doubles it. Background follows its own model definition. Neither μ nor its confidence interval is a direct network output.</p><p>Applying the same inference rules to every subset yields comparable W₆₈ values. AUC remains a useful classification diagnostic, but cannot replace the final inference objective.</p>`,'§ I; § IV Statistical inference and attribution');
  add('Data and processing','The inputs are already simulated samples','The project reads two MC members of the ATLAS 2020 educational collection.',
    `${flow([['Physics process','Scattering and decay'],['Simulation chain','Shower / detector / reconstruction'],['ROOT files','This project starts here']])}${two(table(['Sample','DSID','Project label'],[['ggH125_ZZ4lep','345060','signal = 1'],['llll','363490','background = 0']]),`<p><strong>Collision energy:</strong> 13 TeV</p><p><strong>Normalization:</strong> 10 fb⁻¹</p><p><strong>Final state:</strong> 2e2μ</p><p class="small">Only these two simulated members enter the study.</p>`)}${caution('The upstream chain is schematic. Member-specific generator, shower, FSR and detector configurations have not been fully verified.')}`,
    `<p>MC simulation samples possible physical processes, followed by simulation and reconstruction that produce records of lepton momenta, types and charges. ROOT is a common high-energy physics file format; its mini tree can be viewed as an event table with many columns.</p><p>A controlled HTTPS downloader checks the contracted filenames, sizes and SHA-256 hashes. Signal labels follow member identity. The background name llll alone does not establish a pure qq̄→ZZ process.</p><p>This guide uses aggregate evidence without opening event payloads. The data contract and Appendix C identify the sources. Software versions, perturbative orders and the origins of negative weights require separate physical provenance validation. A generic simulation diagram is not a verified generation configuration.</p>`,'§ II A; Appendix C.1 Samples and normalization');
  add('Data and processing','From a collision record to four leptons','Fixed selection and pairing rules reconstruct two Z systems.',
    two(V.decay(),`${flow([['Quality and triggers','Identification, isolation, matching'],['Four leptons','Exactly 2e + 2μ; total charge 0']])}<div style="height:1cqw"></div>${table(['Step','Rule'],[['Ordered pT','20 / 15 / 10 / 7 GeV'],['Z₁ pair','SFOS pair closest to the Z mass'],['Z₂ pair','Remaining SFOS pair'],['Four-lepton window','105 ≤ m₄ℓ &lt; 140 GeV']])}`),
    `<p>e⁻/e⁺ and μ⁻/μ⁺ denote electrons/muons and their antiparticles. The star in Z* indicates an off-shell system: at approximately 125 GeV, both Z systems cannot simultaneously have their usual on-shell masses. The drawing shows decay relationships only.</p><p>Good leptons pass tight identification. Track and calorimeter isolation divided by pT must each be below 0.3. The electron/muon |d₀/σd₀| limits are 5/3; |z₀/coshη| is below 0.5 mm. Acceptance requires electron |η|&lt;2.47 and muon |η|&lt;2.7. An electron or muon trigger must fire and at least one good lepton must match a trigger object.</p><p>Leptons are ordered by decreasing pT. SFOS means same flavour, opposite sign. All SFOS masses exceed 5 GeV; selected pairs satisfy 50&lt;mZ₁&lt;106 GeV and 12&lt;mZ₂&lt;115 GeV. These rules are fixed before ranking.</p><p>The study does not establish results for 4e/4μ pairing and exchange effects. Invalid four-vectors, undefined angles or nonfinite features fail the analysis rather than being imputed.</p>`,'§ II A Population and reconstruction');
  add('Data and processing','MC records and expected yields differ','Each MC record has a weight. A physical yield is a sum of weights, not a row count.',
    `${f(`${sub('w','i')}${mo('=')}<mfrac><mrow>${mi('L')}${mi('σ')}${mi('k')}${sub('ε','f')}${msupGen('w','i')}</mrow><mrow>${mo('∑')}${msupGen('w','j')}</mrow></mfrac>`,'Physical event weight from luminosity, cross section, correction factors and normalized generator weight')}${two(`<div class="insight"><b>7,221</b><span>signal physical groups in the template role</span></div><div class="insight"><b>2.76832</b><span>normalized expected signal count</span></div>`,`<div class="insight"><b>590</b><span>background physical groups in the template role</span></div><div class="insight"><b>2.49785</b><span>normalized expected background count</span></div>`)}${note('Physical yields retain signed weights. Training uses a nonnegative surrogate weight for a different purpose.')}`,
    `<p>L is integrated luminosity, σ the configured effective cross section, and k and εf the correction and filter factors. Here k=εf=1 and L=10,000 pb⁻¹. Their units combine to an expected count. The denominator sums signed generator weights across the generated sample, not just the current file's rows.</p><p>For a role fraction r inside the historical development fraction pdev=0.8, yield weights also divide by pdev×r to compensate for subsampling. Do not add already compensated role yields together as if they were disjoint contributions to one prediction.</p><p>A negative MC weight is a contribution to a simulation calculation, not a negative-probability event. Matching, subtraction or interference can generate signed weights, but their actual source here has not been inferred from the sign alone. Training uses |w| divided by the mean |w| in that training class; validation AUC uses |w|.</p><p>The approximately 2.77 signal and 2.50 background expectations belong to this restricted process model, not the full experimental four-lepton channel.</p>`,'§ II B; eq:weight; Table I');
  add('Data and processing','One MC population, five statistical roles','Roles separate parameter learning, method choices and diagnostics. Physical groups stay together.',
    `<div class="bar-track"><span style="width:40%;background:#2374ab">train 40%</span><span style="width:10%;background:#6384a0">val 10%</span><span style="width:20%;background:#c66b16">cal 20%</span><span style="width:20%;background:#16836b">template 20%</span><span style="width:10%;background:#8b5db5">assess 10%</span></div>${table(['Role','Purpose'],[['Training','Fit standardization and network parameters'],['Validation','Checkpoint selection and early stopping'],['Calibration','Propose score thresholds'],['Template','Joint support checks, yields and variances'],['Assessment','Frozen parent for diagnostics']])}${caution('These fractions are within the historical 80% development population. A new split or seed does not erase prior access.')}`,
    `<p>Think of five workstations. Training learns the model; validation chooses a training checkpoint; calibration proposes a score boundary; templates estimate category yields; assessment diagnoses the frozen prescription.</p><p>event_group_id combines simulation channel and event number. Multiple representations of one physical event remain in the same role so correlated records are not treated as independent evidence.</p><p>In joint-support-v1, template events support both threshold feasibility and yield estimation, so those steps are dependent. Coverage validation must include the full selection procedure. The historical access review is a single-researcher self-review with independent=false. Role isolation alone does not establish independent confirmation.</p><details><summary>Check: why not tune the threshold after examining assessment?</summary><p>That would feed evaluation outcomes back into method selection. A modified method needs an exploratory label and a separately designed confirmation.</p></details>`,'§ II B Weights and statistical roles');
  add('Features and design','A and B: individual leptons and pairs','Each group is a different physical description of the same event.',
    two(V.geometry(),`<div class="feature-item">${group('A')} <strong>Single-lepton kinematics · 8 inputs</strong><p>Four pT and four η values, ordered by pT.</p></div><div class="feature-item" style="margin-top:2cqw">${group('B')} <strong>Dilepton systems · 4 inputs</strong><p>mZ₁, mZ₂, ΔRZ₁, ΔRZ₂.</p></div>${note('B supplies pair relationships directly, potentially making them easier for a finite network to learn.')}`),
    `<p>pT is momentum perpendicular to the beam, in GeV. Pseudorapidity η=−ln tan(θ/2) describes direction relative to the beam. φ is the azimuth around it. ΔR=√[(Δη)²+(Δφ)²] is a standard angular distance.</p><p>A supplies four pT and four η values rather than complete lepton four-vectors. B adds each pair's invariant mass from four-vector addition and its internal ΔR. Derived features from the same event are not independent new observations.</p><p>A useful representation need not add physical information. Precomputing relationships may help a small MLP with finite training data. Claims about that learner must be distinguished from claims about an ideal model with unlimited capacity.</p>`,'§ III A; Table II; eq:pairmass');
  add('Features and design','C and D: system motion and decay geometry','C describes overall motion; D describes relative directions in specified reference frames.',
    two(V.angles(),`<div class="feature-item">${group('C')} <strong>System kinematics · 2 inputs</strong><p>pT,4ℓ and ΔφZZ.</p></div><div class="feature-item" style="margin-top:2cqw">${group('D')} <strong>Angular5 · 5 inputs</strong><p>cosθ*, cosθ₁, cosθ₂, φdecay, φproduction.</p></div>${caution('The sketch shows planes only. Angle signs depend on charge ordering, beam direction and frame conventions.')}`),
    `<p>C contains the transverse momentum of the summed four-lepton four-vector and the azimuthal separation of the Z systems. These may reflect production and acceptance, but this comparison does not isolate which physical mechanism causes a benefit.</p><p>For D, θ* compares Z₁ with the boosted positive laboratory beam direction in the four-lepton rest frame. Each decay-plane normal is the negative-lepton momentum crossed with the positive-lepton momentum. The two oriented plane angles are measured about Z₁ in [−π,π). θ₁ and θ₂ are defined in the respective Z rest frames, using the negative lepton and the direction opposite to the other system.</p><p>The azimuths enter as raw scalar angles with linear standardization, not sine/cosine pairs. Wrap boundaries may affect a finite network, but their contribution to the observed negative D attribution has not been isolated.</p>`,'§ III A Angular conventions');
  add('Features and design','Fifteen subsets, separately retrained','There are 2⁴−1=15 nonempty subsets and one inclusive-count baseline.',
    `${two(`<div class="chips">${H4L.D.subsets.filter(Boolean).map(s=>`<span class="chip">${s}</span>`).join('')}</div><div style="height:1.5cqw"></div>${table(['Inputs','Dimension'],[['BC','4 + 2 = 6'],['AC','8 + 2 = 10'],['ABCD','8 + 4 + 2 + 5 = 19'],['∅ / M0off','0; constant score 0.5']])}`,`${flow([['Hold fixed','Roles, training rules and inference'],['Change','Which feature groups the network sees']])}${note('BC is trained from scratch on six inputs. It is not an ABCD network with columns masked at evaluation.')}`)}${caution('All classifiers omit explicit m₄ℓ. Correlated kinematic inputs can still carry mass information; no mass decorrelation is applied.')}`,
    `<p>For every nonempty S, train a separate network using the same roles and training rules. Five seeds per subset give 75 networks. Seeds change initialization and training randomness while sharing the underlying MC; they are not five independent datasets.</p><p>The groups are not independent phase-space coordinate blocks. Approximately massless leptons obey mᵢⱼ²=2pTᵢpTⱼ[cosh(Δη)−cos(Δφ)]. Removing a mass column cannot remove all mass dependence from correlated inputs, and the mass window has already selected events.</p><p>M0off is a deterministic constant score of 0.5, not a trained zero-input network. Its five identities align seed bookkeeping and have identical widths. The low category is structurally empty and the high category contains all accepted events.</p>`,'§ III A–B; eq:pairmass');
  add('Neural networks','The actual network architecture','Select groups to change input dimension. Hidden widths remain 64, 64 and 32.',
    `<div data-widget="network"></div>`,
    `<p>A multilayer perceptron (MLP) maps an input vector to a number. Circles are a schematic subset of neurons; the displayed dimensions give actual layer widths. Fit each input column's mean and population standard deviation on training events only, transform x′=(x−mean)/std, and replace a zero standard deviation by 1. Freeze that transform for all other roles.</p><p>Each hidden layer applies Linear, LayerNorm and SiLU. The first two also apply Dropout with p=0.1. The output is one unrestricted logit; sigmoid maps it to a score between 0 and 1. LayerNorm uses epsilon 10⁻⁵.</p><p>Changing input dimension changes first-layer parameter count. This comparison fixes hidden layers and training rules rather than matching total parameter count exactly. The browser only illustrates architecture and published aggregates; it does not train networks or score event payloads.</p>`,'§ III B Network fitting; ResearchClassifier');
  add('Neural networks','How hidden layers turn features into a score','Linear combinations extract patterns; nonlinear activations express more complex relationships.',
    `${flow([['Linear','z = Wx + b'],['LayerNorm','Normalize activations within one sample'],['SiLU','z · sigmoid(z)']])}${two(`${f(`${mi('a')}${mo('=')}<mfrac>${mi('z')}<mrow>${mn(1)}${mo('+')}<msup>${mi('e')}<mrow>${mo('−')}${mi('z')}</mrow></msup></mrow></mfrac>`,'SiLU equals z divided by one plus exp minus z')}<p class="math-note">W here is a learned weight matrix, distinct from interval width W₆₈.</p>`,`<h3>The final sigmoid</h3><p>Very negative logit → near 0<br>logit = 0 → 0.5<br>Very positive logit → near 1</p><p class="small">A higher score favours the training signal label.</p>`)}${note('Dropout randomly suppresses some activations during training. It is disabled for evaluation.')}`,
    `<p>A Linear neuron sums weighted inputs and adds a bias. Stacking only linear layers remains a linear map; SiLU adds nonlinearity. LayerNorm normalizes activations within one sample and differs from column standardization fitted across training events.</p><p>For a hand-written neuron with x=(1,2), W=(0.3,−0.1), b=0.2, z=0.3 and SiLU(z)≈0.172. These are teaching values, not trained parameters.</p><p>A score orders events. Because surrogate optimization weights and signed physical yields define different measures, the score is not automatically a calibrated physical posterior probability, nor is its logit automatically a physical likelihood ratio.</p>`,'§ III B Network fitting');
  add('Neural networks','Training against known MC labels','Binary cross-entropy penalizes errors; AdamW updates the parameters.',
    `${f(`${mi('ℓ')}${mo('=')}${mo('−')}${mo('[')}<mrow>${mi('y')}${mi('log')}${mi('p')}${mo('+')}<mfenced><mrow>${mn(1)}${mo('−')}${mi('y')}</mrow></mfenced>${mi('log')}<mfenced><mrow>${mn(1)}${mo('−')}${mi('p')}</mrow></mfenced></mrow>${mo(']')}`,'Binary cross entropy: minus y log p plus one minus y times log one minus p')}${two(flow([['Forward','Features → logit'],['Loss','Compare with MC labels'],['Backward','Gradient → parameter update']]),table(['Setting','Paper value'],[['Optimizer','AdamW'],['Learning rate / decay','10⁻³ / 10⁻⁴'],['Batch size','1,024'],['Maximum epochs','200'],['Computation','CPU · float32']]))}${note('The optimized objective is classification loss. W₆₈ is computed after training and is not part of the loss.')}`,
    `<p>y=1 denotes signal, y=0 background, and p is the sigmoid score. Signal incurs −log p; background incurs −log(1−p). The implementation uses the numerically stable binary_cross_entropy_with_logits.</p><p>Each event loss is multiplied by |physical_weight| divided by the mean |physical_weight| of its training class, followed by a batch mean. Each class has mean optimization weight 1, but different event counts mean class total loss weights need not match.</p><p>AdamW uses gradients and their history with weight decay. A batch is the set used for one update; an epoch visits the training sample once. The study uses a fixed architecture and prescription, rather than architecture search or inference-aware training such as INFERNO.</p>`,'§ III B Training objective and settings');
  add('Neural networks','Validation selects a checkpoint','AUC measures signal/background ordering. Five seeds probe training variation.',
    `${two(`${flow([['Each epoch','Compute validation AUC'],['Save the best','Minimum gain 10⁻⁴'],['Stop','20 epochs without enough gain']])}${note('AUC near 0.5 means nearly random ordering. Larger AUC means better ordering under this nonnegative evaluation measure.')}`,`<div class="big-number">15 × 5 = 75</div><p>Train each nonempty subset separately.<br>Seeds: 42, 43, 44, 45, 46.</p><div class="insight"><b>+ 5</b><span>deterministic M0off identities<br>80 nominal results in total</span></div>`)}${caution('Validation AUC also selects the checkpoint, so it is not a separate untouched test metric.')}`,
    `<p>A ROC curve shows true-positive versus false-positive rates as the threshold changes. AUC is its area; it can be interpreted as the chance that a signal event outranks a background event, with ties handled by convention and absolute physical weights here.</p><p>Early stopping makes 200 epochs an upper bound. Stop after 20 epochs without sufficient AUC improvement and retain the best saved checkpoint.</p><p>Matching seed labels define controlled pairing, but different first-layer sizes change random optimization trajectories. The 75 fixed networks are reused for attribution. Computing each Shapley term does not trigger retraining.</p>`,'§ III B; § V C Classification and inference rankings');
  const scoreDots=Array.from({length:34},(_,i)=>V.circle(45+(i%17)*36,110+Math.floor(i/17)*42,7,i%5===0?V.colors.signal:V.colors.background)).join('');
  add('Scores and categories','Continuous scores become two categories','Low-score events remain in the likelihood. The threshold partitions events rather than discarding them.',
    `${V.svg(`${scoreDots}${V.line(360,45,360,215,'axis','stroke-dasharray="6 5"')}${V.text(360,30,'Frozen threshold t','large')}${V.text(170,220,'Low: score < t','large')}${V.text(535,220,'High: score ≥ t','large')}${V.line(40,260,650,260,'axis')}${V.text(40,286,'0','label')}${V.text(650,286,'1','label')}${V.text(345,320,'Score locations are schematic','tiny')}`,'All events enter low or high categories; equality goes to high',700,345)}${note('The 105–140 GeV mass window has one mass bin. The comparison is two category counts versus one inclusive count.')}`,
    `<p>Each subset has its own trained network and score, so its category assignment can differ. The common comparison rule does not require a common numerical threshold across models.</p><p>The paper uses raw scores without a conditional CDF transformation or adversarial mass decorrelation. Scores below the threshold enter low; scores equal to or above it enter high. Tied events are not split using labels or event IDs.</p><p>One mass bin does not resolve a mass peak. Benefits can include implicit mass information encoded in the inputs; the study does not establish additional gains on top of a resolved mass-peak fit.</p>`,'§ IV A Score categories and the common template');
  add('Scores and categories','Thresholds follow joint-support rules','Propose quantiles, check MC support, then take the feasible point nearest the median.',
    `${flow([['Propose 19 points','Calibration background quantiles k/20'],['Check support','Both roles, processes and categories'],['Select and freeze','Minimize (|k−10|, k)']])}${two(`${f(`${mi('ρ')}${mo('=')}<mfrac><mrow>${mo('|')}${mi('y')}${mo('|')}</mrow><mrow>${mo('∑')}${mo('|')}${sub('w','i')}${mo('|')}</mrow></mfrac>${mo('≥')}${mn('.2')}`,'Cancellation ratio at least 0.2')}${f(`${sub('N','eff')}${mo('=')}<mfrac><msup>${mi('y')}${mn(2)}</msup>${mi('V')}</mfrac>${mo('≥')}${mn(20)}`,'Signed effective sample size at least 20')}`,`<p>Every required cell needs positive occupancy, yield y and variance V.</p><p><strong>75 / 75</strong> nominal thresholds selected k=10.</p><p class="small">A resample may select another feasible point. No feasible point means failure.</p>`)}${caution('This rule does not minimize W₆₈. The projected histogram proposes quantiles; physical templates retain their signed yields.')}`,
    `<p>Calibration background scores first enter 20 equal bins on [0,1], with signed yields yb and physical-group variances Vb. To propose quantiles despite negative bins, minimize Σ(zb−yb)²/Vb subject to zb≥0 and Σzb=Σyb; zero-variance bins are fixed to zero. This preserves total yield and is neither simple clipping nor absolute-weight quantiles.</p><p>Propose k/20 for k=1…19 from the projected normalized histogram. Check each calibration/template × signal/background × low/high cell for positive occupancy, yield and variance, ρ≥0.2 and Neff≥20. Here y=Σg Wg and V=Σg Wg², with Wg the contribution of a whole physical group.</p><p>Order feasible points by (|k−10|,k): closest to the median first, lower quantile on a tie. If all fail, retain the failure without relaxing support or drawing replacements. M0off has a structurally empty category and uses the inclusive baseline path.</p>`,'§ IV A; eq:projection; eq:support');
  add('Scores and categories','A real BC example: signal in the high category','For seed 42, background is nearly balanced, while most signal enters the high category.',
    two(`<div class="legend"><span><i class="dot" style="background:${V.colors.background}"></i>Background b</span><span><i class="dot" style="background:${V.colors.signal}"></i>Signal s</span></div>${V.categories()}`,`${table(['Category','s','b'],[['Low','0.23310','1.26935'],['High','2.53522','1.22850'],['Total','2.76832','2.49785']])}${note('s/b ≈ 2.06 in high and ≈ 0.18 in low. Separate counts retain their different sensitivities to μ.')}<p class="small">Weighted expected counts can be noninteger.</p>`),
    `<p>An inclusive count retains only total s≈2.77 and b≈2.50. Two categories also retain where signal tends to occur. An additional high-category event and a low-category event can therefore constrain signal strength differently.</p><p>These values come from the selected aggregate BC seed-42 model specification. The stored data retain full precision; displayed numbers are rounded. Summing categories restores the common yields because low-score events were retained.</p><p>This explains how classification may help inference. Stability of the threshold and category yields under new MC is a separate question. Next, first understand inference with known templates, then include their finite-simulation uncertainty.</p>`,'§ IV A BC seed-42 template example');
  add('Likelihood and intervals','μ changes expectations; likelihood compares fits','For each category c, the expected count is λc = μsc + bc.',
    `${f(`${sub('λ','c')}${mo('=')}${mi('μ')}${sub('s','c')}${mo('+')}${sub('b','c')}`,'Expected count in category c equals mu s c plus b c')}${table(['Teaching counts','μ = 0','μ = 1','μ = 2'],[['Signal μs','0','3','6'],['Total μs+b','2','5','8']],'Hand-written example s=3, b=2; not published yields.')}${two(`${f(`${mi('P')}<mfenced><mrow>${mi('n')}${mo('|')}${mi('λ')}</mrow></mfenced>${mo('=')}<mfrac><mrow><msup>${mi('λ')}${mi('n')}</msup><msup>${mi('e')}<mrow>${mo('−')}${mi('λ')}</mrow></msup></mrow><mrow>${mi('n')}${mo('!')}</mrow></mfrac>`,'Poisson probability lambda to n times exp minus lambda divided by n factorial')}<p class="math-note">T0 first treats s and b as exactly known.</p>`,`<h3>Why Poisson?</h3><p>It describes count fluctuations around a given mean.</p><p>Multiply category likelihoods:</p>${f(`${mi('ℒ')}${mo('=')}${mo('∏')}${mi('Pois')}<mfenced><mrow>${sub('n','c')}${mo('|')}${mi('μ')}${sub('s','c')}${mo('+')}${sub('b','c')}</mrow></mfenced>`,'Product of category Poisson likelihoods')}`)}`,
    `<p>Likelihood fixes the observed n and varies μ to compare how well models explain those observations. It is not a probability distribution for μ; the paper does not specify a prior and compute a Bayesian posterior.</p><p>Poisson count fluctuations exist even with precisely known expectations. Finite-MC template uncertainty instead comes from estimating those expectations with limited simulated events.</p><p>T0 is the fixed-template model and omits template uncertainty. Real observed counts are integers. An Asimov construction later substitutes noninteger means without random fluctuations; the parameter-dependent Poisson log-likelihood still defines the ratio because factorial terms cancel.</p>`,'§ IV B; eq:likelihood (T0 explanation)');
  add('Likelihood and intervals','T1 also includes template statistics','Signal and background each receive an adjustable γ, constrained by auxiliary information.',
    `${f(`${sub('λ','c')}${mo('=')}${mi('μ')}${sub('s','c')}${sub('γ','s,c')}${mo('+')}${sub('b','c')}${sub('γ','b,c')}`,'Expected count with signal and background template multipliers gamma')}${two(`${flow([['Category counts','Constrain combinations of μ and γ'],['Auxiliary constraints','Finite MC limits deviations of γ']])}${f(`${mi('τ')}${mo('=')}<mfrac><msup>${mi('y')}${mn(2)}</msup>${mi('V')}</mfrac>${mo(',')}${mi('V')}${mo('=')}${mo('∑')}<msup>${sub('W','g')}${mn(2)}</msup>`,'Auxiliary effective count tau is yield squared divided by variance')}`,`<p>A <strong>nuisance parameter</strong> affects the fit but is not the target μ.</p><p><strong>Profiling:</strong> hold μ fixed and choose the best-fitting γ.</p><p class="small">pyhf shapesys uses independent process/category Poisson auxiliary constraints.</p>`)}${caution('Effective counts for signed MC form an approximation. Convergence and positive yields alone do not validate coverage.')}`,
    `<p>The full likelihood is ∏c Pois(nc | μscγs,c+bcγb,c) × ∏p,c Pois(ap,c | τp,cγp,c), where p labels signal/background and a is the auxiliary observation. Nominal Asimov values are a=τ and γ=1. A larger τ usually gives a tighter relative template constraint.</p><p>Aggregate a physical group's weights before squaring: V=Σg Wg². Correlated records must not be squared as independent events. Structural-zero bins do not enter the active fit; active bins must meet the implemented off-diagonal covariance check.</p><p>The model includes prescribed template-statistical nuisances, not every experimental systematic. The signed effective-count approximation needs independent applicability validation. Fixed-template T0 intuition cannot replace the actual T1 result.</p>`,'§ IV B; eq:likelihood; eq:tau');
  add('Likelihood and intervals','Read W₆₈ from a likelihood curve','Asimov data use expectations at μ=1 instead of a fluctuating observation.',
    `<div data-widget="likelihood"></div>`,
    `<p>The statistic is q(μ)=−2 log[ℒ(μ,γ̂̂(μ))/ℒ(μ̂,γ̂)]. The denominator maximizes over all allowed parameters; the numerator fixes μ and optimizes only γ. A larger q means worse agreement relative to the best fit.</p><p>The nominal 68% threshold is q≤0.9889464815; 95% uses 3.8414588207. μ is nonnegative, with numerical search ceiling 20. Retain a lower endpoint at zero. If no upper crossing exists, record an unbounded interval rather than inventing a width. W₆₈=μup−μlow.</p><p>This widget uses hand-written T0 counts s=(1,3), b=(3,1), Asimov n=(4,4), without γ. Moving μ probes the curve; merging categories changes the illustrative model. It is not a paper T1 refit and creates no new scientific result.</p><p>Each paper candidate uses its own nominal count vector, including auxiliary expectations, while the network is fixed. The threshold relies on an asymptotic χ² approximation. Actual coverage is a separate validation question.</p>`,'§ IV B; eq:profile; eq:width');
  add('Likelihood and intervals','Better AUC need not mean a narrower interval','AUC evaluates score ordering. Inference uses specific category yields and template errors.',
    two(V.aucPlot(),`${table(['Metric','What enters'],[['AUC','Absolute-weight ordering across thresholds'],['W₆₈','Physical yields, finite MC and profiling']])}${f(`${sub('ℐ','T0')}<mfenced>${mi('μ')}</mfenced>${mo('=')}${mo('∑')}<mfrac><msup>${sub('s','c')}${mn(2)}</msup><mrow>${mi('μ')}${sub('s','c')}${mo('+')}${sub('b','c')}</mrow></mfrac>`,'Fixed-template Fisher information is the sum of s squared divided by mu s plus b')}<p class="math-note">Fisher information provides local T0 intuition, not a replacement for T1 interval calculation.</p>`),
    `<p>With exactly known s and b, Fisher information measures local likelihood sensitivity to μ. Cauchy–Schwarz gives Σ sc²/(μsc+bc) ≥ stot²/(μstot+btot). Equality holds when categories have the same signal/background composition.</p><p>This compares retaining versus merging the same fixed categories. Switching BC to ABCD retrains the network and changes category boundaries, so it is not a simple refinement. T1 also introduces MC-dependent nuisances. ABCD therefore need not outperform BC, and W≈1/√I cannot substitute for actual intervals.</p><p>AC has the highest median AUC; BC has the smallest median W₆₈. ABCD has higher median AUC than BC but a wider interval. More inputs, better classification and better inference require separate checks.</p>`,'§ IV B eq:fisher; § V C','auc_width');
  add('Subset performance','Comparison 1: which W₆₈ is smallest?','Each cell is one subset/seed width. The main ranking sorts five-seed medians in ascending order.',
    `<div data-widget="ranking" class="compact"></div>`,
    `<p>The core comparison data are 16 subsets/baselines × five seeds = 80 widths. The analysis does not directly rank a variable distribution from A against one from B, or compare network weight magnitudes.</p><p>For the main ranking, take each subset's five-width median and sort small to large. Selecting a seed changes the displayed single-seed ranking while all five width columns remain. AUC mode sorts large to small for comparison. M0off has no recorded training-validation AUC and remains blank.</p><p>Median W₆₈ is approximately 1.51162 for BC, 1.51524 for AC, 1.53593 for ABCD and 1.66372 for the baseline. This is exploratory nominal performance. AC ranks first for seeds 42/46, BC for 43/44 and BCD for 45, so median rank one does not imply winning every seed.</p>`,'§ V A; Appendix A Complete nominal comparison','subset_widths');
  add('Subset performance','Pair first, then summarize the improvement','Compare S and T within each seed before taking the median of the five improvements.',
    `<div data-widget="pairwise"></div>`,
    `<p>Relative improvement is Rk(S,T)=1−W(S,k)/W(T,k). Positive R favours S. For the absolute difference ΔW=W(S,k)−W(T,k), negative ΔW favours S. Remember their opposite sign conventions.</p><p>Pairing preserves the correspondence of seed blocks. In general median[1−WS/WT] is not 1−median(WS)/median(WT). Shapley and interactions likewise are computed per seed before summarizing.</p><p>The paired median improvements of BC/AC over ABCD are approximately 1.30%/1.42%; over M0off they are 9.14%/8.92%. These percentages have different denominators. The 105 pairs are the fifteen nonempty subsets compared two at a time, not 105 independent experiments.</p>`,'§ IV C eq:relative; § V A','compact_comparisons');
  add('Introducing attribution','Shapley: how do we share a joint benefit?','Measure each group’s incremental benefit in every entry order, then average.',
    `${two(V.shapleyBasics(),`<h3>Two orders, equal weight</h3><p>Benefit means interval narrowing:<br><strong>W before − W after.</strong></p><div class="insight"><b style="color:${V.colors.A}">0.35</b><span>Shapley value of A<br>(0.4 + 0.3) ÷ 2</span></div><div class="insight"><b style="color:${V.colors.B}">0.15</b><span>Shapley value of B<br>(0.1 + 0.2) ÷ 2</span></div><p class="small">Total 0.50 = 2.0 − 1.5: all improvement is allocated.</p>`)}${note('<strong>Why average?</strong> Looking only at first or last entry privileges one context. Equal weighting of all orders includes overlap and complementarity across contexts.')}${caution('This is a hand-written two-group example. The paper has four groups and 4! = 24 orders. Contributions have units of μ interval width, not percentages of physical information.')}`,
    `<p>Shapley values come from cooperative game theory: participants create a joint benefit, and a rule allocates that benefit to each participant. Here participants are feature groups, coalitions are input subsets, and the benefit is interval narrowing relative to the empty baseline.</p><p>In the teaching example W(∅)=2.0, W(A)=1.6, W(B)=1.8, W(AB)=1.5. For A→B the gains are 0.4 and 0.1; for B→A they are 0.2 and 0.3. Hence A receives (0.4+0.3)/2=0.35 and B (0.1+0.2)/2=0.15. Their sum 0.50 equals the total improvement: the efficiency identity.</p><p>A marginal contribution asks how much a group adds to the groups already present. A alone improves by 0.4, but adding A after B improves by 0.3. A single addition or deletion does not describe the average across contexts.</p><p>Every order has equal weight. Symmetry assigns equal contributions to participants with identical effects; a participant with no increment in any coalition receives zero. This mathematical allocation rule does not assert physical independence or equal importance.</p><p>The paper fixes seed k and defines vₖ(S)=−W₆₈(S,k) from the full sixteen-coalition vector. It calculates exact four-group Shapley values, then summarizes seeds. Slide 27 provides real-data arithmetic. Existing networks are reused rather than retrained for each order.</p><p>Positive contributions mean average narrowing; negative contributions mean average widening. Zero can include cancellation of positive and negative contexts. This is workflow attribution, not single-event SHAP or a causal effect. A negative average does not imply deletion helps in every context.</p>`,'§ IV C; eq:shapley; eq:efficiency (two-group teaching example)');
  add('Group contributions','Comparison 2: average benefit of adding a group','Treat A/B/C/D as participants and average each group’s marginal contribution over all orders.',
    `${f(`${sub('v','k')}<mfenced>${mi('S')}</mfenced>${mo('=')}${mo('−')}${sub('W','68')}<mfenced><mrow>${mi('S')}${mo(',')}${mi('k')}</mrow></mfenced>`,'Coalition value is negative nominal interval width')}${two(flow([['Existing subset S','Read its width'],['Add group G','Read the width of S ∪ G'],['Marginal contribution','W(S) − W(S∪G)']]),`<h3>Positive means narrower</h3><p>A group can have different effects in different coalitions.</p><p>Four groups give <strong>4! = 24</strong> orders. Compute each increment, then average.</p>${note('BC versus AC alone cannot isolate the average contribution of B versus A. Shapley combines all contexts.')}`)}`,
    `<p>This is a cooperative-game accounting framework: A/B/C/D are players, S is a coalition and v(S)=−W₆₈(S). The minus sign makes higher value mean a narrower interval.</p><p>Along A→B→C→D, B contributes v(AB)−v(A). Along C→B→D→A it contributes v(BC)−v(C). Context dependence can reflect overlapping features, complementarity, finite training and category compression together.</p><p>Averaging all orders yields Shapley values. Efficiency, symmetry, dummy-player and additivity axioms characterize the allocation rule but do not establish causality. Attribution describes the complete retraining–threshold-selection–compression–inference procedure, rather than why one event received a high score.</p>`,'§ IV C; eq:shapley; eq:efficiency');
  add('Group contributions','Calculate Shapley from sixteen real widths','Select a group and seed to inspect its eight predecessor coalitions and a specific entry order.',
    `<div data-widget="shapley"></div>`,
    `<p>For a fixed G, the other three groups have eight subsets S. The formula is φG,k=ΣS [|S|!(3−|S|)!/4!]×[v(S∪G)−v(S)]. An individual subset of size 0/1/2/3 receives weight 1/4, 1/12, 1/12, 1/4.</p><p>Why these weights? If exactly S precedes G, those groups have |S|! internal orders and the remaining groups have (3−|S|)! orders after G. Divide by all 24 orders. The eight weights sum to one and exactly reproduce permutation averaging.</p><p>For each seed, ΣG φG,k = v(ABCD)−v(∅)=W(∅)−W(ABCD). Taking a separate median for each group generally does not preserve that identity.</p><p>Nominal median contributions are A≈0.01502, B≈0.06222, C≈0.06094 and D≈−0.01110 in signal-strength width units. Exact enumeration removes approximation from sampling orders, not statistical uncertainty.</p>`,'§ IV C eq:shapley/efficiency; § V B','shapley');
  add('Group contributions','Comparison 3: complementarity or overlap?','A conditional interaction is a second difference of four coalition values. Specify both GH and context S.',
    `<div data-widget="interaction"></div>`,
    `<p>IGH|S = v(S∪GH)−v(S∪G)−v(S∪H)+v(S). Equivalently, compare the marginal benefit of G when H is present with its benefit when H is absent, keeping S fixed.</p><p>Positive interaction means joint benefit exceeds the sum of separate benefits in that context; negative means diminishing joint returns. Six group pairs and four contexts give 24 conditional interactions. These are neither mutual information nor causal synergy.</p><p>Unconditional median interactions are approximately AC +0.04246, AB −0.05344 and BC −0.02312. Thus BC can have the best median width and a negative interaction: high total performance does not require strongest complementarity.</p><p>Subset ranking asks which inputs perform best; Shapley asks a group's average contribution; interaction asks whether two groups change one another's increment. MC 95% ranges for unconditional AC/BC include zero, so complementarity or redundancy is not confirmed.</p>`,'§ IV C eq:interaction; § V B; Appendix B');
  add('Validation and conclusions','Stable seeds do not settle overall stability','Five seeds share the MC. They probe only part of the randomness in the training procedure.',
    two(V.dotPlot(['BC','AC','ABCD',''].map(s=>({label:s||'M0off',value:H4L.median(H4L.D.seeds.map(k=>H4L.width(s,k))),points:H4L.D.seeds.map(k=>H4L.width(s,k))})),[1.48,1.69],'Five nominal widths per subset, sharing the underlying MC'),`<h3>Three types of repetition</h3>${table(['Repeat','Probe'],[['Initialization/training','Training-seed stability'],['MC physical groups','Finite template/calibration variation'],['Poisson observations','Conditional interval coverage']])}${note('Vertical offsets separate overlapping points. Their spread is not a confidence interval.')}`),
    `<p>Seeds vary training randomness while models retain the same data split. Sample fluctuations, physical modelling bias or historical selection feedback are not removed by changing initialization five times.</p><p>BC and AC are narrower than ABCD in all five matched seeds, a useful descriptive stability pattern. It is not evidence from five independent MC replications. The winning subset itself changes with seed.</p><p>The workflow also enumerates 5⁵=3125 ordered resamples of the five seed vectors to describe median stability. That remains conditional on the shared MC and training rules; it does not supply an overall confidence interval.</p>`,'§ IV C Seed summaries; § V A');
  add('Validation and conclusions','Finite MC: resample groups and rebuild inference','The 200 bootstrap replicas keep networks fixed, reselect thresholds and rebuild templates and attribution.',
    `${flow([['Resample whole groups','Calibration and template separately'],['Share each role draw','Use it across all candidates'],['Recompute','Threshold → template → W → attribution']])}${two(`<div class="big-number">200 / 200</div><p>All prescribed replicas are numerically valid.</p><div class="insight"><b>112</b><span>nonmedian threshold selections<br>among 15,000 selections</span></div>`,`${f(`${mi('y')}${mo('*')}${mo('=')}${mo('∑')}${sub('m','g')}${sub('W','g')}${mo(',')}${mi('V')}${mo('*')}${mo('=')}${mo('∑')}${sub('m','g')}<msup>${sub('W','g')}${mn(2)}</msup>`,'Resampled yield sums multiplicity times group weight; variance sums multiplicity times squared group weight')}<p class="math-note">Drawing a group m times adds m variance contributions, not the square of an m-fold weight.</p>${caution('Networks are not retrained. Generator/detector variations and full selection-aware calibration are outside these ranges.')}`)}`,
    `<p>For n physical groups in a role, draw n groups with replacement: multiplicities follow Multinomial(n;1/n,…,1/n). Draws are not stratified by process. Calibration and template draws are independent; each role's draw is shared across candidates for paired comparisons.</p><p>Fixed networks and mass grids are reused, but every draw reruns joint-support selection and inference. This captures finite calibration/template MC effects and retains threshold-selection variability.</p><p>A 95% percentile range uses the 2.5% and 97.5% quantiles of replica estimates. Each replica first calculates its five-seed median estimand. With 200 replicas, each tail has only about five order statistics. The ranges lack full selection-aware coverage calibration, are not total confidence intervals and must not be added in quadrature to seed spreads.</p>`,'§ VI A; eq:bootstrap');
  const mcRows=[['AC','BC'],['AC','ABCD'],['BC','ABCD']].map(([l,r])=>({label:`${l} − ${r}`,value:H4L.median(H4L.D.seeds.map(k=>H4L.width(l,k)-H4L.width(r,k))),interval:H4L.mc('pairwise',{left:l,right:r},'delta_width68_left_minus_right')}));
  add('Validation and conclusions','Ranges crossing zero limit the conclusion','A nominally narrower interval and an advantage resolved against MC variation are different claims.',
    two(`<h3>MC 95% ranges: paired width differences</h3>${V.dotPlot(mcRows,[-.065,.05],'Paired MC ranges for AC/BC and full-input comparisons include zero',true)}<p class="small">ΔW &lt; 0 favours the left subset.</p>`,`<h3>MC 95% ranges: Shapley contributions</h3>${V.dotPlot(H4L.D.attribution.map(r=>({label:r.group,value:r.median,interval:H4L.mc('contributions',{group:r.group}),color:V.colors[r.group]})),[-.025,.095],'B/C contribution ranges stay positive; A/D include zero',true)}<p class="small">Positive contribution means average narrowing.</p>`,'equal'),
    `<p>Left dots show nominal median paired width differences; lines show fixed-network event-MC bootstrap 95% percentile ranges. AC−BC, AC−ABCD and BC−ABCD all include zero. These ranges do not confirm that compact inputs outperform all inputs, or establish whether AC or BC is better.</p><p>On the right, positive B/C ranges support their interpretation as principal contributors conditional on these fixed networks. A/D ranges cross zero. Although D is negative in every nominal seed, a nonzero negative population contribution has not been established.</p><p>Including zero does not prove equivalence. Noninferiority or equivalence requires prespecified margins and an independent design. These are not simultaneous multiple-comparison confidence intervals and lack full selection calibration.</p>`,'§ VI A; Table III','mc_uncertainty');
  add('Validation and conclusions','Assess width, coverage and applicability','Coverage asks how often repeated intervals contain the injected true value.',
    two(V.coverage(),`${table(['Diagnostic','What changes or is checked'],[['model-self','Generate from the fitted model; closure'],['assessment','Use the frozen assessment parent'],['T2','Resample calibration and reselect thresholds']])}${caution('Lines are five-seed ranges, not coverage confidence intervals. Numerical validity does not establish independent validation.')}`),
    `<p>A nominal 68% interval with only 50% repeated-experiment coverage would be unreliable despite being narrow. Asymptotic profile thresholds need specific coverage checks at low counts and near the μ≥0 boundary.</p><p>Model-self and assessment use 500 trials per candidate, seed and injection at μ=0,1,2. Model-self checks closure against its own model; assessment uses a frozen parent but lacks independent access review. T1 auxiliary Poisson observations are regenerated.</p><p>T2 uses 20 outer calibration-group bootstraps, each with 100 inner trials at μ=1 per seed, holding networks and template/assessment parents fixed. The twenty outer plans are shared across seeds. The 2,000 inner fits are not 2,000 independent full-procedure replications.</p><p>Common random numbers (CRN) couple total counts and category allocations while preserving marginal Poisson laws. This is an artificial coupling, not physical event covariance across candidates. Independent allocation sensitivity, full selection-aware coverage and physical applicability remain unvalidated.</p><p>Judge the workflow by software correctness, nominal gains, uncertainty/coverage, physical provenance and independence together. The evidence supports an exploratory comparison, not a confirmed precision gain or a physics measurement.</p>`,'§ VI B–C; Table IV; § VII Conclusions','coverage');
  add('Review and sources','Explain the full chain to someone else','Features change classification and category composition, then inference. Attribution and reliability need further checks.',
    `${flow([['Input subsets','Physical representations'],['Networks/categories','Separate training → counts'],['Inference','Common T1 → W₆₈'],['Interpret/validate','Rank / Shapley / coverage']])}${two(`<h3>Supported takeaways</h3><ul><li>BC/AC are compact candidates for prospective study.</li><li>B/C contribute most to nominal narrowing.</li><li>More inputs or higher AUC need not lower W₆₈.</li></ul>`,`<h3>Limits still matter</h3><ul><li>Compact-versus-full MC difference ranges include zero.</li><li>Negative D does not mean angles lack physics information.</li><li>Independent confirmation and full coverage calibration remain pending.</li></ul>`)}<div class="source-links"><a href="../../paper/latex/main.tex" target="_blank" rel="noopener">Paper source</a><a href="../../paper/selected-snapshot.json" target="_blank" rel="noopener">Selected evidence identity</a><a href="../methods-and-evaluation.md" target="_blank" rel="noopener">Methods</a><a href="README-en.md" target="_blank" rel="noopener">Guide and sources</a></div>`,
    `<h3>Five checks for understanding</h3><details><summary>1. Where did the raw data come from?</summary><p>Two existing MC members of the ATLAS 2020 educational collection. The network does not generate collision samples; member-specific upstream configurations remain partly unverified.</p></details><details><summary>2. What do subsets compare?</summary><p>The nominal Asimov W₆₈ obtained from their own trained networks and templates through the same T1 procedure.</p></details><details><summary>3. How are rankings and contributions obtained?</summary><p>Rank five-seed median widths. Compute Shapley marginal gains over all entry orders within each seed, then summarize seeds.</p></details><details><summary>4. How can BC rank best with a negative interaction?</summary><p>Total performance differs from complementarity. Strong but partly overlapping groups can perform well together while having diminishing joint returns.</p></details><details><summary>5. Why is narrowing insufficient?</summary><p>An overly narrow interval can undercover. Validate finite MC, the full selection procedure, physical applicability and independence.</p></details><h3>Glossary</h3><p><strong>MC:</strong> Monte Carlo simulation. <strong>Coalition:</strong> a subset of groups. <strong>Logit:</strong> the real output before sigmoid. <strong>Asimov:</strong> expectations substituted for random observations. <strong>Profile likelihood:</strong> likelihood optimized over nuisances at fixed target parameter. <strong>Bootstrap:</strong> resampling with replacement. <strong>Coverage:</strong> fraction of repeated intervals containing truth.</p><h3>Sources and dates</h3><p>The content follows the 2026-10-12 paper. On 2026-10-26, local results.json and provenance.json hashes and report identity matched paper/selected-snapshot.json. The earlier manuscript reported the aggregate package unavailable. Its restored byte binding does not revalidate event payloads, all historical execution records or physical applicability.</p><p>Selected report: <code>${H4L.D.source.report_artifact_id}</code>. Qualification remains exploratory_posthoc, independent=false, selection_aware_coverage=unvalidated and primary_claim_eligible=false. Core scope: synthetic_software_defaults_not_physics_validation.</p><p>References follow the paper's references.bib, including Shapley (1953), Cowan et al. on asymptotic likelihood methods, pyhf and weighted-template statistics. Original figures link to committed PDFs. Offline reading needs only this folder; paper links need the repository's relative layout.</p>`,'§ VII; Data and computational materials; Appendices A–C');
  function msupGen(a,b){return `<msubsup>${mi(a)}${mi(b)}${mt('gen')}</msubsup>`;}
  return slides;
})();
